## Submitted testbench
```systemverilog
module tb;
  // DUT port declarations
  logic clk;
  logic rst;
  logic [15:0] s_axis_tdata;
  logic s_axis_tvalid;
  logic s_axis_tready;
  logic [15:0] m_axis_tdata;
  logic m_axis_tvalid;
  logic m_axis_tready;
  logic rxd;
  logic txd;
  logic tx_busy;
  logic rx_busy;
  logic rx_overrun_error;
  logic rx_frame_error;
  logic [15:0] prescale;

  // Instantiate DUT
  uart dut (.*);

  // Clock generation (125 MHz → period 8 time‑units)
  initial begin
    clk = 0;
    forever #(4) clk = ~clk; // toggle every 4 time‑units
  end

  // Parameters
  localparam int PRESCALE_VAL = 5;
  localparam int BIT_CLKS = PRESCALE_VAL * 8; // clocks per UART bit

  // Wait for N falling edges of clk
  task automatic wait_clks (input int n);
    repeat (n) @(negedge clk);
  endtask

  // Send one UART byte (8N1, LSB first)
  task automatic uart_send_byte (input [7:0] data);
    // idle (high)
    rxd = 1'b1;
    // start bit
    rxd = 1'b0;
    wait_clks(BIT_CLKS);
    // data bits
    for (int i = 0; i < 8; i = i + 1) begin
      rxd = data[i];
      wait_clks(BIT_CLKS);
    end
    // stop bit
    rxd = 1'b1;
    wait_clks(BIT_CLKS);
  endtask

  // Main stimulus
  initial begin
    // Reset
    rst = 1;
    #100;
    rst = 0;
    #100;

    // Non‑zero prescale required by coverage checks
    prescale = 16'd5;

    // 1️⃣  Send the stalled word 0x3C
    uart_send_byte(8'h3C);

    // Wait a short amount so that busy is high and bit_cnt is ≈2‑9
    repeat (30) @(posedge clk);

    // 2️⃣  Assert m_axis_tready for one clock cycle (DUT input)
    m_axis_tready = 1;
    #(8);               // one full clock period
    m_axis_tready = 0;

    // 3️⃣  Small gap before the next payload
    repeat (10) @(posedge clk);

    // 4️⃣  Send the accepting word 0xA5
    uart_send_byte(8'hA5);

    // Give the coverage model time to evaluate
    repeat (20000) @(posedge clk);

    $finish;
  end

  // Keep UART line idle
  initial rxd = 1'b1;

  // Keep unused AXI inputs at known values
  initial begin
    s_axis_tdata = 0;
    s_axis_tvalid = 0;
  end

  // Prescale must stay non‑zero (coverage rule)
  initial prescale = 16'd5;
endmodule
```

